const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const villarrica = ee.Geometry.Point([-56.45, -25.75]).buffer(10000); // 10km buffer around Villarrica

  // Define time periods
  const period2021 = ['2021-01-01', '2021-12-31'];
  const period2016 = ['2016-01-01', '2016-12-31'];

  // 2. Data Acquisition
  const chirps2021 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(period2021[0], period2021[1])
    .filterBounds(villarrica);

  const chirps2016 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(period2016[0], period2016[1])
    .filterBounds(villarrica);

  // Check collection sizes
  const size2021 = chirps2021.size().getInfo();
  const size2016 = chirps2016.size().getInfo();

  console.log(`2021 Images: ${size2021}`);
  console.log(`2016 Images: ${size2016}`);

  if (size2021 === 0 || size2016 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate annual precipitation totals
  const total2021 = chirps2021.sum().select('precipitation');
  const total2016 = chirps2016.sum().select('precipitation');

  // Check valid pixel counts
  const count2021 = total2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: villarrica,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const count2016 = total2016.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: villarrica,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`2021 Valid Pixels: ${count2021}`);
  console.log(`2016 Valid Pixels: ${count2016}`);

  if (count2021 === 0 || count2016 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation values
  const mean2021 = total2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: villarrica,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const mean2016 = total2016.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: villarrica,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 5. Validation & Final Answer
  console.log(`2021 Mean Rainfall: ${mean2021 ? mean2021.toFixed(1) : 'null'} mm`);
  console.log(`2016 Mean Rainfall: ${mean2016 ? mean2016.toFixed(1) : 'null'} mm`);

  if (mean2021 === null || mean2016 === null || 
      isNaN(mean2021) || isNaN(mean2016) ||
      mean2021 < 0 || mean2016 < 0) {
    console.log("<answer>C3</answer>");
  } else if (mean2021 > mean2016) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
